var failures = new System.Collections.Generic.List<object>();
var assemblies = System.AppDomain.CurrentDomain.GetAssemblies();
foreach (var assembly in assemblies)
{
    try { assembly.GetName(); }
    catch (System.Exception error)
    {
        string location;
        try { location = assembly.Location; } catch (System.Exception locationError) { location = locationError.GetType().Name; }
        failures.Add(new { assembly = assembly.FullName, location, error = error.GetType().Name, message = error.Message });
    }
}
return new { inspected = assemblies.Length, failures, compiling = UnityEditor.EditorApplication.isCompiling, playing = UnityEditor.EditorApplication.isPlaying };
